import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CfwCq2QB.js";const r="/dev-go-docs/shots/0.2.3/en/light/options-general.png",s="/dev-go-docs/shots/0.2.3/en/dark/options-general.png",m=JSON.parse('{"title":"General & appearance","description":"","frontmatter":{},"headers":[],"relativePath":"en/settings/general.md","filePath":"en/settings/general.md"}'),c={name:"en/settings/general.md"};function i(d,e,l,p,h,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="general-appearance" tabindex="-1">General &amp; appearance <a class="header-anchor" href="#general-appearance" aria-label="Permalink to &quot;General &amp; appearance&quot;">​</a></h1><p>In one line: theme, UI language, the popup&#39;s default page, shortcuts, sync, and backup — all under Settings → General.</p><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><ul><li><strong>Theme</strong>: Light / Dark / Auto. Auto goes dark from 18:00 to 6:00; applies to the popup, settings, side panel, and new tab together</li><li><strong>UI language</strong>: Follow browser / Chinese / English. Switching takes effect immediately — open pages included, no refresh needed. The extension&#39;s name and shortcut descriptions follow the browser&#39;s own language (they come from the manifest, which manual switching can&#39;t override)</li></ul><img src="'+r+'" alt="General settings"><p><em>Settings → General: appearance, language, shortcuts, sync, and backup.</em></p><img src="'+s+'" alt="General settings in dark theme"><p><em>General settings in dark theme.</em></p><h2 id="popup" tabindex="-1">Popup <a class="header-anchor" href="#popup" aria-label="Permalink to &quot;Popup&quot;">​</a></h2><p><strong>Default page</strong>: which page the popup opens on when you click the toolbar icon or press <code>Alt+1</code> (Translate / Network / Resources / Features). Network and Resources also have dedicated shortcuts, <code>Alt+3</code> and <code>Alt+4</code>.</p><h2 id="shortcuts" tabindex="-1">Shortcuts <a class="header-anchor" href="#shortcuts" aria-label="Permalink to &quot;Shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Default key</th></tr></thead><tbody><tr><td>Open popup (default page)</td><td><code>Alt+1</code></td></tr><tr><td>Open AI assistant (side panel)</td><td><code>Alt+2</code> (Chrome only)</td></tr><tr><td>Open popup Network page</td><td><code>Alt+3</code></td></tr><tr><td>Open popup Resources page</td><td><code>Alt+4</code></td></tr><tr><td>Toggle page translation</td><td>Not bound; bindable</td></tr></tbody></table><p>Browsers don&#39;t let extensions change their own shortcuts:</p><ul><li><strong>Chrome / Edge</strong>: change them at <code>chrome://extensions/shortcuts</code>; this page refreshes the display once you&#39;re back</li><li><strong>Firefox</strong>: <code>about:addons</code> → gear icon at the top right → &quot;Manage Extension Shortcuts&quot;</li></ul><h2 id="sync-across-devices" tabindex="-1">Sync across devices <a class="header-anchor" href="#sync-across-devices" aria-label="Permalink to &quot;Sync across devices&quot;">​</a></h2><p>Quick links and proxy configuration sync to your other devices with your browser account (Chrome caps sync storage at 100KB; usage is shown here). &quot;Sync now&quot; triggers a manual run and shows the last sync time.</p><h2 id="backup" tabindex="-1">Backup <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;Backup&quot;">​</a></h2><p><strong>Export</strong> writes a JSON file with all settings (quick links, network, translation, AI models, selection actions, and the rest); <strong>Import</strong> restores it. API keys are <strong>never</strong> written to backup files and need re-entering after a move. See <a href="/dev-go-docs/en/settings/sync.html">Backup &amp; sync</a>.</p>',18)])])}const k=t(c,[["render",i]]);export{m as __pageData,k as default};
